  {
   var revision=++livePresetRevision;
   LivePreset=null;
   if(colorLuts==null || !CanEditBooth)return;
   try
   {
    var configured=await settingsService.GetAsync(CancellationToken.None);
    if(configured?.LiveViewPresetId==null)return;
    using(var data=await colorLuts.GetLiveAsync(configured.LiveViewPresetId.Value,CancellationToken.None))
    {
     if(data==null)return;
     var m=data.Metadata;
     var compiled=await Task.Run(()=>new PhotoBooth.Color.D3D11.LivePreviewLut(data.Values,m.CubeSize,Math.Max(0,Math.Min(100,configured.LiveViewPresetStrengthPercent))/100f,m.DomainMinR,m.DomainMinG,m.DomainMinB,m.DomainMaxR,m.DomainMaxG,m.DomainMaxB));
     if(revision==livePresetRevision && CanEditBooth)LivePreset=compiled;
    }
   }
   catch(Exception error){log.LogWarning(error,"Live preset unavailable; original preview retained");}
  }
