  async Task RefreshActiveConfigurationSummaryAsync(Guid eventId)
  {
   var configuration=await eventManagement.GetActiveConfigurationAsync(eventId,CancellationToken.None);
   var workflow=await settingsService.GetAsync(CancellationToken.None)??new Settings();
   createGif=workflow.CreateGif;createVideo=workflow.CreateVideo;Raise(nameof(CreateGif));Raise(nameof(CreateVideo));
   if(CanEditBooth&&workflow.BoothSettingsConfigured){photoCount=workflow.PhotoCount;countdown=workflow.CountdownSeconds;gifDuration=workflow.GifFrameDurationMilliseconds/1000d;waitingTimeout=ToWaitingTimeoutLabel(workflow.WaitingTimeoutSeconds);}
   else if(configuration!=null){photoCount=configuration.PhotoCount;countdown=configuration.CountdownSeconds;gifDuration=configuration.GifFrameDurationMilliseconds/1000d;waitingTimeout=ToWaitingTimeoutLabel(configuration.WaitingTimeoutSeconds);}
   autoFlip=workflow.AutoFlip;imageRotation=workflow.ImageRotationDegrees;usePortraitCustomer=workflow.CustomerLayoutMode==CustomerLayoutMode.Portrait;
   var frameCount=CanEditBooth?BoothLibrarySelection.Frames(await frameLibrary.GetAllAsync(CancellationToken.None),workflow).Count:configuration?.FrameIds?.Count??0;
   var presetCount=CanEditBooth?BoothLibrarySelection.Presets(await presetLibrary.GetAllAsync(CancellationToken.None),workflow).Count:configuration?.PresetIds?.Count??0;
   FrameSummary=frameCount+" frame";PresetSummary=presetCount+" preset";WorkingFolder=CaptureRoot;StorageInfo(WorkingFolder);
   foreach(var name in new[]{nameof(PhotoCount),nameof(Countdown),nameof(GifDuration),nameof(WaitingTimeout),nameof(AutoFlip),nameof(ImageRotation),nameof(LiveViewRotation),nameof(LiveViewScaleX),nameof(UsePortraitCustomer)})Raise(name);
  }
