  PendingPreview pendingPreview; int presentingPreview; long beautyRevision;
  sealed class PendingPreview { internal object Image; internal CancellationTokenSource Session; internal long Revision; }
  void OnLiveBeautyFrameReady(object sender,LiveBeautyPreviewFrameEventArgs args)
  {
   var session=liveToken;var revision=Interlocked.Read(ref beautyRevision);
   if(args?.Frame?.ImageData==null || session==null || session.IsCancellationRequested)return;
   Interlocked.Increment(ref previewOutputFrames);
   if(args.BeautyApplied){Interlocked.Increment(ref previewBeautyFrames);Interlocked.Add(ref previewBeautyTicks,(long)(args.ProcessingMilliseconds*Stopwatch.Frequency/1000d));}
   object display=args.Frame.ImageData;
   if(args.Pixels!=null){var p=args.Pixels;var image=System.Windows.Media.Imaging.BitmapSource.Create(p.Width,p.Height,96,96,System.Windows.Media.PixelFormats.Bgr24,null,p.Pixels,p.Stride);image.Freeze();display=image;}
   Interlocked.Exchange(ref pendingPreview,new PendingPreview{Image=display,Session=session,Revision=revision});QueuePreview();
  }
  void QueuePreview()
  {
   if(Interlocked.CompareExchange(ref presentingPreview,1,0)!=0)return;
   var dispatcher=System.Windows.Application.Current?.Dispatcher;
   if(dispatcher!=null&&!dispatcher.CheckAccess())dispatcher.BeginInvoke(new Action(PresentPreview),System.Windows.Threading.DispatcherPriority.Render);else PresentPreview();
  }
  void PresentPreview()
  {
   try{var item=Interlocked.Exchange(ref pendingPreview,null);if(item!=null&&ReferenceEquals(liveToken,item.Session)&&!item.Session.IsCancellationRequested&&item.Revision==Interlocked.Read(ref beautyRevision))LiveImage=item.Image;}
   finally{Interlocked.Exchange(ref presentingPreview,0);if(Volatile.Read(ref pendingPreview)!=null)QueuePreview();}
  }
