  async Task EnsureLiveViewAsync(){var camera=SelectedCamera;if(camera==null||!camera.IsConnected){await StopLive();return;}await liveGate.WaitAsync();try{if(customerModeActive)return;if(liveToken!=null&&string.Equals(liveCameraId,camera.Id,StringComparison.Ordinal))return;await StopLiveCore(null,false);liveBeautySettings=await beautySettingsService.GetAsync(CancellationToken.None)??new BeautySettings();liveBeautyFailed=false;liveBeauty.Reset();liveBeauty.UpdateSettings(liveBeautySettings);Interlocked.Exchange(ref presentedFrames,0);Interlocked.Exchange(ref metricsPresentedFrames,0);Interlocked.Exchange(ref previewOutputFrames,0);Interlocked.Exchange(ref previewBeautyFrames,0);Interlocked.Exchange(ref previewBeautyTicks,0);for(var attempt=0;attempt<3;attempt++){CancellationTokenSource cts=null;try{cts=new CancellationTokenSource();await live.StartAsync(camera.Id,cts.Token);liveToken=cts;liveCameraId=camera.Id;liveLoopTask=LiveLoop(camera.Id,cts.Token);ConnectionStatus="Connected";return;}catch(Exception e){cts?.Cancel();cts?.Dispose();log.LogWarning(e,"Live View start failed (attempt {Attempt}/3)",attempt+1);try{await Task.Delay(1000);}catch{}}}}finally{liveGate.Release();}}
