  async Task StopLiveCore(CameraInfo camera,bool force){var token=liveToken;var loop=liveLoopTask;var cameraId=liveCameraId??camera?.Id;var hadLiveSession=token!=null;liveToken=null;liveLoopTask=null;liveCameraId=null;if(token!=null)token.Cancel();if(loop!=null)try{await loop;}catch(OperationCanceledException){}catch(Exception e){log.LogDebug(e,"Live View loop stopped with an error");}liveBeauty.Reset();Interlocked.Exchange(ref presentedFrames,0);Interlocked.Exchange(ref metricsPresentedFrames,0);if((hadLiveSession||force)&&!string.IsNullOrWhiteSpace(cameraId))try{await live.StopAsync(cameraId,CancellationToken.None);}catch(Exception e){log.LogWarning(e,"Live View stop failed");}token?.Dispose();}
  void ResetCameraUiState(){cameraEpoch++;CameraProperties.Clear();Cameras.Clear();SelectedCamera=null;LiveImage=null;CurrentFps=0;resolutionWidth=0;resolutionHeight=0;Raise(nameof(Resolution));}
  async Task LiveLoop(string id,CancellationToken token){var fpsWatch=Stopwatch.StartNew();var metrics=Stopwatch.StartNew();var requests=0;var uniqueFrames=0;var duplicateFrames=0;var emptyFrames=0;long fetchTicks=0;var lastSignature=0;while(!token.IsCancellationRequested){try{var stageStarted=Stopwatch.GetTimestamp();var frame=await live.GetFrameAsync(id,token);fetchTicks+=Stopwatch.GetTimestamp()-stageStarted;requests++;var submitted=false;if(frame?.ImageData!=null){var signature=FrameSignature(frame.ImageData);if(signature!=lastSignature){lastSignature=signature;uniqueFrames++;if(resolutionWidth!=frame.Width||resolutionHeight!=frame.Height){resolutionWidth=frame.Width;resolutionHeight=frame.Height;Raise(nameof(Resolution));}liveBeauty.Submit(frame,token);submitted=true;}else duplicateFrames++;}else emptyFrames++;if(fpsWatch.ElapsedMilliseconds>=1000){CurrentFps=Interlocked.Exchange(ref presentedFrames,0);fpsWatch.Restart();}if(metrics.ElapsedMilliseconds>=10000){var seconds=Math.Max(.001,metrics.Elapsed.TotalSeconds);var outputFrames=Interlocked.Exchange(ref previewOutputFrames,0);var actualPresented=Interlocked.Exchange(ref metricsPresentedFrames,0);var beautyFrames=Interlocked.Exchange(ref previewBeautyFrames,0);var beautyTicks=Interlocked.Exchange(ref previewBeautyTicks,0);using(var process=Process.GetCurrentProcess())log.LogInformation("Admin Live View metrics {Seconds:F1}s: requests {RequestFps:F1} fps, unique/acquired {AcquiredFps:F1} fps, preview-output {OutputFps:F1} fps, presented {PresentedFps:F1} fps, fetch avg {FetchMs:F2} ms, beauty avg {BeautyMs:F2} ms ({BeautyFrames} frames), duplicates {Duplicates}, empty {Empty}, managed {ManagedMb:F1} MB, private {PrivateMb:F1} MB",seconds,requests/seconds,uniqueFrames/seconds,outputFrames/seconds,actualPresented/seconds,AverageMilliseconds(fetchTicks,requests),AverageMilliseconds(beautyTicks,beautyFrames),beautyFrames,duplicateFrames,emptyFrames,GC.GetTotalMemory(false)/1048576d,process.PrivateMemorySize64/1048576d);metrics.Restart();requests=uniqueFrames=duplicateFrames=emptyFrames=0;fetchTicks=0;}await Task.Delay(submitted ? 15 : 8,token);}catch(OperationCanceledException){break;}catch(Exception e){CurrentFps=0;log.LogWarning(e,"Live View unavailable; retrying");try{await Task.Delay(500,token);}catch(OperationCanceledException){break;}}}}
  static double AverageMilliseconds(long ticks,int count)=>count<=0?0d:ticks*1000d/Stopwatch.Frequency/count;
  static int FrameSignature(byte[] data){unchecked{var hash=data.Length;var step=Math.Max(1,data.Length/32);for(var i=0;i<data.Length;i+=step)hash=(hash*397)^data[i];return hash;}}
   public async Task PersistSettingsAsync(){await settingsSaveGate.WaitAsync();try{var s=await settingsService.GetAsync(CancellationToken.None)??new Settings();s.PreferredCameraId=SelectedCamera?.IsConnected==true?SelectedCamera.Id:s.PreferredCameraId;await settingsService.SaveAsync(s,CancellationToken.None);}finally{settingsSaveGate.Release();}}
   async Task SaveSettings(){if(!CanEditBooth)return;await settingsSaveGate.WaitAsync();try{var s=await settingsService.GetAsync(CancellationToken.None)??new Settings();s.BoothSettingsConfigured=true;s.CreateGif=CreateGif;s.CreateVideo=CreateVideo;s.PhotoCount=PhotoCount;s.CountdownSeconds=Countdown;s.GifFrameDurationMilliseconds=(int)Math.Round(GifDuration*1000);s.WaitingTimeoutSeconds=ToWaitingTimeoutSeconds(WaitingTimeout);s.AutoFlip=AutoFlip;s.PreferredCameraId=SelectedCamera?.IsConnected==true?SelectedCamera.Id:s.PreferredCameraId;s.ImageRotationDegrees=ImageRotation;s.CustomerLayoutMode=UsePortraitCustomer?CustomerLayoutMode.Portrait:CustomerLayoutMode.Landscape;s.SaveLocation=ToSaveLocationMode(SaveLocation);await settingsService.SaveAsync(s,CancellationToken.None);Dirty=false;SettingsMessage="Đã lưu thông số booth. Áp dụng từ lượt chụp tiếp theo.";}catch(Exception e){SettingsMessage="Không thể lưu thông số booth. Vui lòng thử lại.";Friendly(e,"Settings could not be saved");}finally{settingsSaveGate.Release();}}
  void SetCameraControls(bool enabled){if(Set(ref cameraControlsEnabled,enabled))Raise(nameof(IsCameraControlsEnabled));}
   void StorageInfo(string path){try{var root=Path.GetPathRoot(path);var drive=new DriveInfo(root);Storage=Math.Round(drive.AvailableFreeSpace/1073741824d,1)+" GB free";}catch{Storage="Unknown";}}
   static string ToSaveLocationLabel(PhotoBooth.Core.Cameras.CameraSaveMode mode)=>mode==PhotoBooth.Core.Cameras.CameraSaveMode.PcAndCard?"Cả hai (Canon only)":"Chỉ lưu ở PC";
   static PhotoBooth.Core.Cameras.CameraSaveMode ToSaveLocationMode(string label)=>label=="Cả hai (Canon only)"?PhotoBooth.Core.Cameras.CameraSaveMode.PcAndCard:PhotoBooth.Core.Cameras.CameraSaveMode.PcOnly;
   static string ToWaitingTimeoutLabel(int seconds)=>seconds==60?"1 phút":seconds==120?"2 phút":seconds==300?"5 phút":seconds==600?"10 phút":seconds==900?"15 phút":"30 giây";
   static int ToWaitingTimeoutSeconds(string label)=>label=="1 phút"?60:label=="2 phút"?120:label=="5 phút"?300:label=="10 phút"?600:label=="15 phút"?900:30;
  void Friendly(Exception e,string text){log.LogError(e,text);ConnectionStatus=text+(string.IsNullOrWhiteSpace(e?.Message)?"":": "+e.Message);}
 }
 public sealed class CameraPropertyRow:ObservableObject { readonly Func<string,Task> changed; string selected; public CameraPropertyRow(CameraProperty model,Func<string,Task> changed){Kind=model.Kind;Values=model.AllowedValues??new string[0];selected=model.Value;IsDisplayOnly=model.Kind==CameraPropertyKind.CameraMode;IsEnabled=model.IsAvailable&&!model.IsReadOnly&&!IsDisplayOnly;this.changed=changed;} public CameraPropertyKind Kind{get;} public string Label=>Kind==CameraPropertyKind.CameraMode?"Camera Mode":Kind==CameraPropertyKind.ShutterSpeed?"Shutter Speed":Kind==CameraPropertyKind.WhiteBalance?"White Balance":Kind==CameraPropertyKind.FocusMode?"Focus Mode":Kind==CameraPropertyKind.MeteringMode?"Metering Mode":Kind==CameraPropertyKind.ExposureCompensation?"Exposure Compensation":Kind.ToString(); public IReadOnlyList<string> Values{get;} public bool IsDisplayOnly{get;} public bool IsEnabled{get;} public string SelectedValue{get=>selected;set{if(IsEnabled&&Set(ref selected,value)&&value!=null)_=changed(value);}} }
